from pathlib import Path
import re
root=Path(__file__).resolve().parents[1];p=root/'dist/adventure.js';s=p.read_text(encoding='utf-8-sig')
s=s.replace("import {project,inside,moveToward} from './navigation.js';", "import {project,inside,moveToward} from './navigation.js';\nimport {customSimulation,defaults as modelDefaults,outcome as modelOutcome,contrasted as modelContrasted,conceptOptions,outputRows} from './simulations.js';")
s=s.replace("'De eindpuzzel van les ${state.chapter+1}'", "`De eindpuzzel van les ${state.chapter+1}`")
s=s.replace('function experimentMarkup(b){', 'function legacyExperimentMarkup(b){')
custom='''function experimentMarkup(b){if(!customSimulation(b))return legacyExperimentMarkup(b);const spec=b.simulationSpec,v={...modelDefaults(spec),...state.expValues[b.id]},controls=spec.parameters.map(p=>{const value=v[p.id];if(p.type==='select')return `<label class="model-control"><span>${esc(p.label)}</span><select data-exp="${p.id}">${p.options.map(o=>`<option value="${esc(o.value)}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label>`;if(p.type==='boolean')return `<label class="model-control model-check"><span>${esc(p.label)}</span><input type="checkbox" data-exp="${p.id}" ${value?'checked':''}></label>`;return `<label class="model-control"><span>${esc(p.label)}</span><input type="range" min="${p.min}" max="${p.max}" step="${p.step||1}" value="${value}" data-exp="${p.id}"><strong data-expvalue="${p.id}">${value}</strong></label>`;}).join('');return `<div class="model-terminal ${b.simulation==='claim-boundary'?'claim-model':''}"><p class="model-label">${esc(spec.title)}</p><div class="model-controls">${controls}</div><div id="model-output"></div><div id="model-visual" aria-hidden="true"></div></div><details class="model-assumptions"><summary>Wat dit model meeneemt en wat niet</summary>${spec.assumptions.map(x=>`<p>${esc(x)}</p>`).join('')}</details><label class="note-label" for="prediction">${esc(spec.predictionPrompt||'Wat verwacht je vóór je deze proef uitvoert?')}</label><textarea id="prediction" data-notes="${b.id}:prediction" placeholder="Mijn verwachting en de reden daarvoor…">${esc(state.notes[`${b.id}:prediction`]||'')}</textarea>${button('Voer deze proef uit','runExperiment')}<div id="experiment-feedback"></div>`;}
'''
s=s.replace('function legacyExperimentMarkup(',custom+'function legacyExperimentMarkup(')
s=s.replace('function expValues(){return Object.fromEntries([...document.querySelectorAll(\'[data-exp]\')].map(e=>[e.dataset.exp,Number(e.value)]));}', '''function expValues(){return Object.fromEntries([...document.querySelectorAll('[data-exp]')].map(e=>[e.dataset.exp,e.type==='checkbox'?e.checked:Number.isFinite(Number(e.value))?Number(e.value):e.value]));}''')
s=s.replace("function refreshExperiment(){const b=activeBeat;if(!b||b.type!=='experiment')return;const v=expValues();", "function refreshExperiment(){const b=activeBeat;if(!b||b.type!=='experiment')return;const v=expValues();if(customSimulation(b)){refreshModel(b,v);return;}")
s=s.replace('function runExperiment(){const b=activeBeat,', 'function runExperiment(){if(customSimulation(activeBeat)){runModelTrial();return;}const b=activeBeat,')
s=s.replace('function finishExperiment(){const b=activeBeat,', 'function finishExperiment(){if(customSimulation(activeBeat)){finishModel();return;}const b=activeBeat,')
s=s.replace("function interpretExperiment(id){const correct=", "function interpretExperiment(id){if(customSimulation(activeBeat)){const o=conceptOptions(activeBeat).find(o=>o.id===id);if(o?.correct)collectBeat();else $('#experiment-feedback').insertAdjacentHTML('beforeend',`<div class=\"small-feedback retry\">${esc(o?.feedback||activeBeat.hint)}</div>`);return;}const correct=")
models='''function refreshModel(b,v){state.expValues[b.id]=v;persist();document.querySelectorAll('[data-expvalue]').forEach(e=>e.textContent=v[e.dataset.expvalue]);const result=modelOutcome(b.simulation,v),format=n=>typeof n==='number'?n.toLocaleString('nl-NL',{maximumFractionDigits:2}):String(n);$('#model-output').innerHTML=outputRows(b.simulationSpec).map(row=>`<div class="model-readout"><span>${esc(row.label)}</span><strong>${esc(format(result[row.id]))}</strong><small>${esc(row.unit||'')}</small></div>`).join('');const count=b.simulation==='sorter'?12:b.simulation==='incentives'?4:20,filled=b.simulation==='sorter'?result.recoveredItems:b.simulation==='incentives'?result.reached:Math.round(v.coveragePercent/5);$('#model-visual').innerHTML=Array.from({length:count},(_,n)=>`<span class="model-item ${n<filled?'active':''}"></span>`).join('');}
function runModelTrial(){const b=activeBeat,v=expValues(),prediction=state.notes[`${b.id}:prediction`]?.trim();if(!prediction){notify('Noteer eerst je verwachting en waarom.');$('#prediction').focus();return;}state.trials[b.id]??=[];const trials=state.trials[b.id],signature=JSON.stringify(v);if(!trials.some(t=>t.signature===signature))trials.push({signature,values:v,prediction,result:modelOutcome(b.simulation,v)});persist();const ready=modelContrasted(b,trials),spec=b.simulationSpec;$('#experiment-feedback').innerHTML=`<p class="trial-record">${trials.length} verschillende proeven bewaard.</p><details class="trial-log"><summary>Bekijk mijn proeflog</summary>${trials.map((t,n)=>`<article><strong>Proef ${n+1}</strong><p>${spec.parameters.map(p=>`${esc(p.label)}: ${esc(t.values[p.id])}`).join(' · ')}</p><p>${outputRows(spec).map(row=>`${esc(row.label)}: ${Number(t.result[row.id]).toLocaleString('nl-NL',{maximumFractionDigits:2})}`).join(' · ')}</p></article>`).join('')}</details><div class="small-feedback">${ready?'Je hebt relevante verschillen naast elkaar gezet. Verklaar het mechanisme en de grens van het model.':spec.contrastRequirements.map(x=>esc(typeof x==='string'?x.label||x:x.id==='baseline'?'Vergelijk een route zonder bescherming onder hoge targetdruk.':'Vergelijk met een beschermde route en voldoende beoordelingsruimte.')).join(' ')}</div>${ready?`<label class="note-label" for="experiment-interpretation">${esc(spec.interpretationPrompt||'Wat verandert in je gecontroleerde vergelijking, en wat kun je hieruit niet afleiden?')}</label><textarea id="experiment-interpretation" data-notes="${b.id}:interpretation">${esc(state.notes[`${b.id}:interpretation`]||'')}</textarea>${button('Onderbouw mijn vergelijking','finishExperiment')}`:''}`;}
function finishModel(){const b=activeBeat;if(!state.notes[`${b.id}:interpretation`]?.trim()){notify('Leg de vergelijking eerst in je eigen woorden uit.');return;}$('#experiment-feedback').innerHTML=`<p>${esc(b.simulationSpec.conceptQuestion||'Welke conclusie wordt door deze vergelijking ondersteund?')}</p><div class="puzzle-cards">${conceptOptions(b).map(o=>button(esc(o.text),'interpretExperiment','puzzle-card',`data-id="${o.id}"`)).join('')}</div>`;}
'''
s=s.replace('function legacyExperimentMarkup(',models+'function legacyExperimentMarkup(')
p.write_text(s,encoding='utf-8')
with (root/'dist/adventure.css').open('a',encoding='utf-8') as f:f.write('''\n.model-terminal{background:#162f32;color:#e0eee2;border:1px solid #638a83;border-radius:7px;padding:19px;margin:15px 0}.model-label{letter-spacing:.08em;text-transform:uppercase;font-size:.66rem!important;color:#c7b57f}.model-controls{display:grid;gap:13px}.model-control{display:grid;grid-template-columns:1fr 1fr 22px;align-items:center;gap:10px;font-size:.74rem}.model-control select{grid-column:2/4;width:100%;background:#e6ecdf;color:#1a332a;border:1px solid #b4c4ad;padding:8px;border-radius:3px}.model-control input{width:100%;accent-color:#b9c27e}.model-check input{width:20px;height:20px}.model-readout{display:grid;grid-template-columns:1fr auto;gap:5px;padding:12px 0;border-top:1px solid #819f9244;font-size:.68rem}.model-readout small{grid-column:1/3;color:#a7bdae;font-size:.55rem}.model-readout strong{font-size:1.1rem;color:#e4c58e}#model-output{margin-top:15px}#model-visual{display:flex;flex-wrap:wrap;gap:5px;padding-top:8px}.model-item{display:block;width:20px;height:20px;border-radius:4px;background:#62584b;border:1px solid #a69b7e}.model-item.active{background:#6d9a79;border-color:#c2d8a1}.claim-model{background:#eee6d0;color:#284437;border-color:#b5a17a}.claim-model .model-label{color:#86643b}.claim-model .model-readout{border-color:#97a48677}.claim-model .model-readout strong{color:#795d33}.claim-model .model-readout small{color:#607e66}.model-assumptions,.trial-log{font-size:.7rem;margin:12px 0}.model-assumptions summary,.trial-log summary{cursor:pointer}.model-assumptions p,.trial-log p{font-size:.7rem!important}.trial-log article{border:1px solid #c2cbb4;padding:12px;margin:9px 0}.trial-log strong{font-size:.7rem}@media(max-width:760px){.model-control{grid-template-columns:1fr;gap:7px}.model-control select{grid-column:auto}.model-control input{max-width:100%}.model-readout{font-size:.65rem}}\n''')
